from solution import VisibilityQueue

def test_claim_visibility_expires_at_deadline():
    queue = VisibilityQueue([{'id': 'a'}, {'id': 'b'}], 5)
    assert queue.claim(0) == {'id': 'a'}
    assert queue.claim(4) == {'id': 'b'}
    assert queue.claim(5) == {'id': 'a'}

def test_acknowledge_removes_item():
    queue = VisibilityQueue([{'id': 'a'}], 5)
    assert queue.acknowledge('a') is True
    assert queue.claim(0) is None
    assert queue.acknowledge('missing') is False

